def _ni(id, title, desc, content, y, mo, d, views, imgs=None):
    """Сокращённый конструктор NewsItem для читаемого seed-списка."""
    return NewsItem(
        id=id,
        title=title,
        description=desc,
        content=content,
        created_at=datetime(y, mo, d, 10, 0, 0, tzinfo=timezone.utc),
        views=views,
        images_json=json.dumps(imgs) if imgs else None,
    )


