# Минимальные просмотры для seed-новостей.
_MIN_VIEWS = {
    "welcome":    103,
    "pu5-launch": 81,
    "n01": 583, "n02": 570, "n03": 559, "n04": 544, "n05": 537,
    "n06": 525, "n07": 515, "n08": 499, "n09": 491, "n10": 477,
    "n11": 466, "n12": 459, "n13": 446, "n14": 438, "n15": 426,
    "n16": 417, "n17": 402, "n18": 395, "n19": 384, "n20": 371,
    "n21": 363, "n22": 349, "n23": 340, "n24": 328, "n25": 311,
}

# Ревизии текстов seed-новостей: при увеличении номера контент подтянется в БД
# (не затрагивает просмотры и не перезаписывает правки, сделанные после этой ревизии).
_SEED_TEXT_REV: dict[str, int] = {
    "n10": 2,
    "n12": 2,
    "n15": 2,
    "n16": 2,
    "n18": 2,
    "n25": 1,
}


def _get_images(item: NewsItem) -> list[str]:
    """Return the list of image URLs for a news item (supports legacy single image_url)."""
    if item.images_json:
        try:
            return json.loads(item.images_json)
        except Exception:
            pass
    if item.image_url:
        return [item.image_url]
    return []


def _apply_seed_text_revision(session: Session, existing: NewsItem, default: NewsItem) -> bool:
    """Обновить title/description/content из дефолта, если ревизия в коде новее."""
    target_rev = _SEED_TEXT_REV.get(default.id, 0)
    if not target_rev:
        return False

    state = session.get(NewsSeedState, default.id)
    applied = state.text_revision if state else 0
    if applied >= target_rev:
        return False

    existing.title = default.title
    existing.description = default.description
    existing.content = default.content
    if default.images_json is not None:
        existing.images_json = default.images_json
        existing.image_url = json.loads(default.images_json)[0] if default.images_json else None

    if state is None:
        state = NewsSeedState(news_id=default.id, text_revision=target_rev)
    else:
        state.text_revision = target_rev
    session.add(state)
    session.add(existing)
    return True


def _seed_default_news(session: Session):
    """Идемпотентный seed дефолтных новостей.

    Логика:
      * если дефолтной новости (по id) ещё нет — создаём её со стартовыми
        значениями `views`;
      * если есть, но `views` меньше минимального стартового значения —
        мягко поднимаем счётчик до минимума;
      * если для id задана `_SEED_TEXT_REV` и ревизия в БД устарела —
        обновляем title/description/content из дефолта.
    """
    changed = False
    for default in _DEFAULT_NEWS:
        existing = session.get(NewsItem, default.id)
        if existing is None:
            session.add(default)
            rev = _SEED_TEXT_REV.get(default.id, 0)
            if rev:
                session.add(NewsSeedState(news_id=default.id, text_revision=rev))
            changed = True
            continue

        min_views = _MIN_VIEWS.get(default.id)
        if min_views and (existing.views or 0) < min_views:
            existing.views = min_views
            session.add(existing)
            changed = True

        if _apply_seed_text_revision(session, existing, default):
            changed = True

    if changed:
        session.commit()


def _item_to_dict(item: NewsItem) -> dict:
    images = _get_images(item)
    return {
        "id": item.id,
        "title": item.title,
        "description": item.description,
        "content": item.content,
        "image_url": images[0] if images else None,
        "images": images,
        "created_at": item.created_at.isoformat() if item.created_at else None,
        "views": item.views,
    }


async def _upload_file(image: UploadFile, news_id: str, idx: int) -> Optional[str]:
    ext = os.path.splitext(image.filename)[1] or ".jpg"
    image_filename = f"{news_id}_{idx}{ext}"
    data = await image.read()

    if is_s3_configured():
        url = upload_image(data, f"news/images/{image_filename}", image.filename)
        if url:
            return url

    IMAGES_DIR.mkdir(parents=True, exist_ok=True)
    (IMAGES_DIR / image_filename).write_bytes(data)
    return f"/api/news/images/{image_filename}"


@router.get("")
def list_news(session: Session = Depends(get_session)):
    _seed_default_news(session)
    items = session.exec(select(NewsItem).order_by(NewsItem.created_at.desc())).all()
    return [_item_to_dict(i) for i in items]


@router.get("/images/{filename}")
def get_image(filename: str):
    path = IMAGES_DIR / filename
    if not path.exists():
        raise HTTPException(404, "Image not found")
    return FileResponse(path)


@router.post("/{news_id}/view")
def increment_view(news_id: str, session: Session = Depends(get_session)):
    item = session.get(NewsItem, news_id)
    if not item:
        raise HTTPException(404, "News not found")
    item.views = (item.views or 0) + 1
    session.add(item)
    session.commit()
    return {"views": item.views}


@router.get("/{news_id}")
def get_news(news_id: str, session: Session = Depends(get_session)):
    item = session.get(NewsItem, news_id)
    if not item:
        raise HTTPException(404, "News not found")
    return _item_to_dict(item)


@router.post("")
async def create_news(
    title: str = Form(...),
    description: str = Form(...),
    content: str = Form(""),
    images: List[UploadFile] = File(default=[]),
    _=Depends(require_editor),
    session: Session = Depends(get_session),
):
    news_id = uuid.uuid4().hex[:8]

    valid_images = [img for img in images if img and img.filename]
    urls: list[str] = []
    for idx, img in enumerate(valid_images):
        url = await _upload_file(img, news_id, idx)
        if url:
            urls.append(url)

    item = NewsItem(
        id=news_id,
        title=title,
        description=description,
        content=content or description,
        image_url=urls[0] if urls else None,
        images_json=json.dumps(urls) if urls else None,
        created_at=datetime.now(timezone.utc),
    )
    session.add(item)
    session.commit()
    session.refresh(item)
    return _item_to_dict(item)


@router.put("/{news_id}")
async def update_news(
    news_id: str,
    title: str = Form(...),
    description: str = Form(...),
    content: str = Form(""),
    images: List[UploadFile] = File(default=[]),
    _=Depends(require_editor),
    session: Session = Depends(get_session),
):
    item = session.get(NewsItem, news_id)
    if not item:
        raise HTTPException(404, "News not found")

    item.title = title
    item.description = description
    item.content = content or description

    valid_images = [img for img in images if img and img.filename]
    if valid_images:
        urls: list[str] = []
        for idx, img in enumerate(valid_images):
            url = await _upload_file(img, news_id, idx)
            if url:
                urls.append(url)
        item.images_json = json.dumps(urls) if urls else None
        item.image_url = urls[0] if urls else None

    session.add(item)
    session.commit()
    session.refresh(item)
    return _item_to_dict(item)


@router.delete("/{news_id}")
def delete_news(news_id: str, _=Depends(require_editor), session: Session = Depends(get_session)):
    item = session.get(NewsItem, news_id)
    if not item:
        raise HTTPException(404, "News not found")
    session.delete(item)
    session.commit()
    return {"ok": True}
